/**
 * {{ombox}} (other pages message box) styles
 *
 * @source https://www.mediawiki.org/wiki/MediaWiki:Gadget-enwp-boxes.css
 * @revision 2021-07-15
 */
table.ombox {
	margin: 4px 10%;
	border-collapse: collapse;
	/* Default "notice" gray */
	border: 1px solid #a2a9b1;
	background-color: #f8f9fa;
	color: #333;
	box-sizing: border-box;
}

/* An empty narrow cell */
.ombox td.mbox-empty-cell {
	border: none;
	padding: 0;
	width: 1px;
}

/* The message body cell(s) */
.ombox th.mbox-text,
.ombox td.mbox-text {
	border: none;
	/* 0.9em left/right */
	padding: 0.25em 0.9em;
	/* Make all mboxes the same width regardless of text length */
	width: 100%;
}

/* The left image cell */
.ombox td.mbox-image {
	border: none;
	text-align: center;
	/* 0.9em left, 0px right */
	/* @noflip */
	padding: 2px 0 2px 0.9em;
}

/* The right image cell */
.ombox td.mbox-imageright {
	border: none;
	text-align: center;
	/* 0px left, 0.9em right */
	/* @noflip */
	padding: 2px 0.9em 2px 0;
}

table.ombox-notice {
	/* Gray */
	border-color: #a2a9b1;
}

table.ombox-speedy {
	/* Pink */
	background-color: #fee7e6;
	color: #333;
}

table.ombox-speedy,
table.ombox-delete {
	/* Red */
	border-color: #b32424;
	border-width: 2px;
}

table.ombox-content {
	/* Orange */
	border-color: #f28500;
}

table.ombox-style {
	/* Yellow */
	border-color: #fc3;
}

table.ombox-move {
	/* Purple */
	border-color: #9932cc;
}

table.ombox-protection {
	/* Gray-gold */
	border-color: #a2a9b1;
	border-width: 2px;
}

/**
 * {{ombox|small=1}} styles
 *
 * These ".mbox-small" classes must be placed after all other
 * ".ombox" classes. "html body.mediawiki .ombox"
 * is so they apply only to other page message boxes.
 *
 * @source https://www.mediawiki.org/wiki/MediaWiki:Gadget-enwp-boxes.css
 * @revision 2021-07-15
 */

/* For the "small=yes" option. */
html body.mediawiki .ombox.mbox-small {
	clear: right;
	float: right;
	margin: 4px 0 4px 1em;
	box-sizing: border-box;
	width: 238px;
	font-size: 88%;
	line-height: 1.25em;
}

@media screen {
	html.skin-theme-clientpref-night table.ombox {
	    background-color: transparent;
	    color: inherit;
	}
}

@media screen and (prefers-color-scheme: dark) {
    /* automatic mode */
    html.skin-theme-clientpref-os table.ombox {
    	background-color: transparent;
    	color: inherit;
    }
}

@media screen and (max-width: 720px) {
  table.ombox {
	margin: 4px auto;
  }
}

.note {
	background-position: left 7px top 50%;
	padding: 0.5em 0.5em 0.5em 40px;
	margin: 0.5em 0;
	overflow: hidden;
	background-color: #f8f9fa;
	color: #333;
	background-repeat: no-repeat;
	border: 1px solid #ddd;
}
.note-inline {
	display: inline-block;
	vertical-align: middle;
}
.note-info {
	background-color: #eaf3ff;
	color: #333;
	/* [[File:OOjs_UI_icon_information-progressive.svg]] */
	background-image: url(https://upload.wikimedia.org/wikipedia/commons/e/ec/OOjs_UI_icon_information-progressive.svg);
	background-size: 25px;
	border-color: #a3caff;
	padding-left: 40px;
	min-height: 25px;
}
.note-reminder {
	background-color: #fff9ea;
	color: #333;
	/* [[File:OOjs_UI_icon_lightbulb-yellow.svg]] */
	background-image: url(https://upload.wikimedia.org/wikipedia/commons/a/a8/OOjs_UI_icon_lightbulb-yellow.svg);
	background-size: 25px;
	border-color: #fc3;
	min-height: 25px;
}
.note-warn {
	background-color: #fff9ea;
	color: #333;
	/* [[File:OOjs_UI_icon_alert-warning.svg]] */
	background-image: url(https://upload.wikimedia.org/wikipedia/commons/3/3b/OOjs_UI_icon_alert-warning.svg);
	background-size: 25px;
	border-color: #fc3;
	min-height: 25px;
}

.note-error {
	background-color: #fee7e6;
	color: #333;
	/* [[File:OOjs_UI_icon_notice-destructive.svg]] */
	background-image: url(https://upload.wikimedia.org/wikipedia/commons/b/bf/OOjs_UI_icon_notice-destructive.svg);
	background-size: 25px;
	border-color: #c33;
	min-height: 25px;
}

@media screen {
	html.skin-theme-clientpref-night .note {
		background-color: transparent;
	    color: inherit;
	}
}

@media screen and (prefers-color-scheme: dark) {
    /* automatic mode */
	html.skin-theme-clientpref-os .note {
		background-color: transparent;
    	color: inherit;
	}
}

/* Styling for [[Template:Mono]] */
.monospaced {
	/* Keep it like this: "monospace, monospace". Those are the rules from [[w:WP:MONO]]. */
	font-family: monospace, monospace;
}

.nowrap,
.nowrap a:before,
.nowrap .selflink:before {
	white-space: nowrap;
}

.nmbox {
	/* clear: both; */
	background: #f8f9fa;
	border: 1px solid var( --border-color-base, #a2a9b1 );
	box-sizing: border-box;
	margin: 2px 0;
	padding: 0;
}
.nmbox * {
	box-sizing: border-box;
}
.nmbox-header {
	background: #eaecf0;
	padding: 4px 0.5em;
	font-weight: bold;
	text-align: center;
	white-space: nowrap
}
.nmbox .mbox-image {
	display: inline-block;
	padding-right: 1em;
}
.nmbox-text {
	border-top: 1px solid var( --border-color-base, #a2a9b1 );
	width: 100%;
	padding: 4px 0.5em;
}
@media screen and (min-width: 768px) {
	.nmbox-header {
		display: table-cell;
		border-right: 1px solid var( --border-color-base, #a2a9b1 );
		width: 1%;
	}
	.nmbox-text {
		border-top: none;
		display: table-cell;
	}
}

@media screen {
	html.skin-theme-clientpref-night .nmbox-header,
	html.skin-theme-clientpref-night  .nmbox {
	    background: transparent;
	    color: inherit;
	}
}

@media screen and (prefers-color-scheme: dark) {
    /* automatic mode */
    html.skin-theme-clientpref-os .nmbox-header,
    html.skin-theme-clientpref-os  .nmbox {
    	background: transparent;
    	color: inherit;
    }
}

