local cfg = {}; -- Don’t touch this line.
-- The link for the “subst:” prefix when the “link subst” parameter is truthy. -- Set to “nil” to disable the “link subst” parameter. cfg["subst-link"] = "Special:MyLanguage/Help:Substitution";
